const raw=$('DB | Load Airtable Sync Context').item.json.sync_context;
const ctx=typeof raw==='string'?JSON.parse(raw):raw;
if(!ctx||ctx.connector_key!=='airtable_primary') throw new Error('AIRTABLE_SYNC_CONTEXT_INVALID');
let gate=ctx.reliability_gate;if(typeof gate==='string')gate=JSON.parse(gate);
const allowed=gate?.allowed===true;
return {sync_context:ctx,should_sync:allowed,skip_reason:allowed?null:(gate?.reason??'CONNECTOR_NOT_READY')};

const raw=$('DB | Load Airtable Sync Context').first().json.sync_context;
const ctx=typeof raw==='string'?JSON.parse(raw):raw;const cfg=ctx.provider_config??{};
const pages=$input.all().map(x=>x.json??{});const rows=pages.flatMap(p=>Array.isArray(p.records)?p.records:[]);
if(rows.length>10000)throw new Error('AIRTABLE_SYNC_RESULT_LIMIT_EXCEEDED');
const expected=String(ctx.currency_code??'').trim().toUpperCase();
const won=new Set((cfg.won_stages??['Closed Won']).map(x=>String(x).toLowerCase()));
const lost=new Set((cfg.lost_stages??['Closed Lost']).map(x=>String(x).toLowerCase()));
const start=new Date(ctx.query_start_at).getTime(),end=new Date(ctx.query_end_at).getTime();
const records=[];let rejected=0;
for(const r of rows){const f=r.fields??{};const id=String(r.id??'').trim();const amount=Number(f['Deal Value']??0);
 const stage=String(f.Stage??'').trim(),low=stage.toLowerCase();const cat=won.has(low)?'won':(lost.has(low)?'lost':'open');
 const valid=id&&Number.isFinite(amount)&&amount>=0&&stage&&/^[A-Z]{3}$/.test(expected);
 if(!valid){rejected++;continue;}
 records.push({source_record_id:id,source_payload:{'Opportunity Name':f['Opportunity Name']??null,'Deal Value':String(amount),
  Stage:stage,revint_currency_code:expected,revint_stage_category:cat}});
}
return [{json:{connector_key:'airtable_primary',query_start_at:new Date(start).toISOString(),
 query_end_at:new Date(end).toISOString(),watermark:new Date(end).toISOString(),source_count:rows.length,
 record_count:records.length,rejected_count:rejected,records,event_id:'AIRTABLE-SYNC-'+String(end)}}];
